export STATE_DIR="$(mktemp -d)/state" && node --input-type=module -e "
import * as b from './bot.mjs';
const now = new Date();
const out = [];
out.push(['no optin marketing', await b.mayEmail(' Ann@Example.com ', 'marketing', now)]);
await b.resubscribe('ann@example.com');
out.push(['optin marketing', await b.mayEmail('ANN@example.com ', 'marketing', now)]);
await Promise.all([b.unsubscribe('ann@example.com'), b.unsubscribe(' Ann@example.com'), b.unsubscribe('ann@example.com')]);
out.push(['after unsub marketing', await b.mayEmail('ann@example.com', 'marketing', now)]);
out.push(['after unsub receipt', await b.mayEmail('ann@example.com', 'receipt', now)]);
await b.resubscribe('ann@example.com');
out.push(['resub marketing', await b.mayEmail('ann@example.com', 'marketing', now)]);
out.push(['bad kind', await b.mayEmail('ann@example.com', 'promo', now)]);
out.push(['bad email', await b.mayEmail('nope', 'receipt', now)]);
for (const [k, v] of out) console.log(k, JSON.stringify(v));
" && echo "--- files:" && find "$STATE_DIR" -type f | wc -l && rm -rf "$(dirname "$STATE_DIR")"

